import numpy as np

# A tiny "trained language model" stand-in: next-token scores from word-pair counts.
corpus = "the cat sat on the mat . the dog sat on the rug .".split()
vocab = sorted(set(corpus))
word_to_id = {w: i for i, w in enumerate(vocab)}
counts = np.zeros((len(vocab), len(vocab)))
for a, b in zip(corpus, corpus[1:]):
    counts[word_to_id[a], word_to_id[b]] += 1


def next_token_scores(token_ids):
    """What a trained Transformer's last position would output: one score per vocabulary word."""
    return counts[token_ids[-1]]


def positional_encoding(seq_len, d_model):
    pos = np.arange(seq_len)[:, None]
    two_i = np.arange(0, d_model, 2)[None, :]
    angle = pos / 10000 ** (two_i / d_model)
    pe = np.zeros((seq_len, d_model))
    pe[:, 0::2] = np.sin(angle)
    pe[:, 1::2] = np.cos(angle)
    return pe


def causal_mask(n):
    return np.tril(np.ones((n, n), dtype=bool))


def layer_norm(x, eps=1e-5):
    mean = x.mean(axis=-1, keepdims=True)
    var = x.var(axis=-1, keepdims=True)
    return (x - mean) / np.sqrt(var + eps)


def generate(score_fn, start_ids, steps):
    ids = list(start_ids)
    for _ in range(steps):
        ids.append(int(np.argmax(score_fn(ids))))
    return ids


pe = positional_encoding(6, 4)
print("positional encoding shape:", None if pe is None else pe.shape)
print("causal mask:")
print(causal_mask(4))
ln = layer_norm(np.array([[1.0, 2.0, 3.0, 4.0]]))
print("layer norm:", None if ln is None else np.round(ln, 3))
ids = generate(next_token_scores, [word_to_id["the"]], steps=6)
if ids is not None:
    print("generated:", " ".join(vocab[i] for i in ids))
